import{dynasties}from"../data.js";export function Contributions(){const e=document.createElement("div");e.className="contributions-container";const n={"Architecture & Art":[],"Science & Literature":[],"Governance & Military":[],"Culture & Religion":[]};dynasties.forEach(e=>{e.contributions.forEach(t=>{const i=t.toLowerCase();i.includes("temple")||i.includes("architecture")||i.includes("painting")||i.includes("sculpture")||i.includes("bronze")||i.includes("built")||i.includes("fort")||i.includes("taj")?n["Architecture & Art"].push({text:t,dynasty:e.name,color:e.color}):i.includes("university")||i.includes("literature")||i.includes("zero")||i.includes("math")||i.includes("science")||i.includes("astronomy")||i.includes("surgery")||i.includes("language")?n["Science & Literature"].push({text:t,dynasty:e.name,color:e.color}):i.includes("admin")||i.includes("revenue")||i.includes("military")||i.includes("naval")||i.includes("governance")||i.includes("warfare")||i.includes("postal")?n["Governance & Military"].push({text:t,dynasty:e.name,color:e.color}):n["Culture & Religion"].push({text:t,dynasty:e.name,color:e.color})})}),e.innerHTML='<h3 class="section-subtitle">Key Contributions by Category</h3>';const t=document.createElement("div");return t.className="contributions-grid",Object.entries(n).forEach(([e,n])=>{const i=document.createElement("div");i.className="contribution-category-card",i.innerHTML=`\n      <h4>${e}</h4>\n      <ul>\n        ${n.map(e=>`\n          <li>\n            <span class="contribution-dynasty" style="color:${e.color}">${e.dynasty}</span>\n            ${e.text}\n          </li>\n        `).join("")}\n      </ul>\n    `,t.appendChild(i)}),e.appendChild(t),e}